const item = $input.item.json || {};
let usdAmount = parseFloat(item.monto_usd || item.usd || 0);
const months = parseInt(item.meses || item.mes || 0);

if (!usdAmount && months) {
  if (months === 1) usdAmount = 8;
  else if (months === 3) usdAmount = 24;
  else if (months === 6) usdAmount = 48;
  else if (months === 12) usdAmount = 84;
}

if (!usdAmount) {
  usdAmount = 8; // Default 1 month
}

// 1. Fetch Paralelo
let paraleloRate = 0;
try {
  const pRes = await this.helpers.httpRequest({
    method: 'GET',
    url: 'https://ve.dolarapi.com/v1/dolares/paralelo',
    headers: { 'User-Agent': 'Mozilla/5.0' },
    json: true,
    timeout: 5000
  });
  paraleloRate = parseFloat(pRes.promedio || 0);
} catch (e) {}

// 2. Fetch Binance P2P
let binanceRate = 0;
try {
  const bRes = await this.helpers.httpRequest({
    method: 'POST',
    url: 'https://p2p.binance.com/bapi/c2c/v2/friendly/c2c/adv/search',
    headers: {
      'User-Agent': 'Mozilla/5.0',
      'Content-Type': 'application/json'
    },
    body: {
      asset: 'USDT',
      fiat: 'VES',
      merchantCheck: false,
      page: 1,
      payTypes: ['PagoMovil'],
      publisherType: null,
      rows: 5,
      tradeType: 'BUY'
    },
    json: true,
    timeout: 5000
  });
  const prices = (bRes.data || []).map(adv => parseFloat(adv.adv?.price || 0)).filter(p => p > 0);
  if (prices.length > 0) {
    binanceRate = prices.reduce((a, b) => a + b, 0) / prices.length;
  }
} catch (e) {}

const effectiveRate = Math.max(paraleloRate, binanceRate, 1);
const totalBs = (usdAmount * effectiveRate).toFixed(2);

return {
  json: {
    tasa_del_dia: effectiveRate.toFixed(2),
    monto_usd: usdAmount,
    total_bs: totalBs,
    banco: 'Bancamiga',
    telefono: '04246861135',
    rif: 'J405259221',
    beneficiario: 'ArialStore C.A.',
    qr_markdown: '![Código QR Pago Móvil](https://raw.githubusercontent.com/totaltvusa/images/main/Arialstorepm.jpeg)',
    resumen_precios_bs: {
      plan_1_mes: (8 * effectiveRate).toFixed(2) + ' Bs ($8)',
      plan_3_meses: (24 * effectiveRate).toFixed(2) + ' Bs ($24)',
      plan_6_meses: (48 * effectiveRate).toFixed(2) + ' Bs ($48)',
      plan_12_meses: (84 * effectiveRate).toFixed(2) + ' Bs ($84)'
    }
  }
};
